const LANGUAGE_KEY = 'controle-viagens-language';
const TRANSLATION_OVERRIDES_KEY = 'controle-viagens-translation-overrides';
type LanguageContextValue = { language: AppLanguage; setLanguage: (language: AppLanguage) => void; t: (text: string) => string; translationOverrides: Record<string, string>; updateTranslation: (key: string, spanish: string) => void };
const LanguageContext = createContext<LanguageContextValue | null>(null);

export function translateText(text: string, language: AppLanguage, overrides: Record<string, string> = {}) { return language === 'es-ES' ? (overrides[text] ?? translations[text] ?? text) : text; }

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<AppLanguage>('pt-BR');
  const [translationOverrides, setTranslationOverrides] = useState<Record<string, string>>({});
  useEffect(() => { AsyncStorage.getItem(LANGUAGE_KEY).then((saved) => { if (saved === 'pt-BR' || saved === 'es-ES') setLanguageState(saved); }); AsyncStorage.getItem(TRANSLATION_OVERRIDES_KEY).then((saved) => { if (saved) { try { setTranslationOverrides(JSON.parse(saved) as Record<string, string>); } catch { setTranslationOverrides({}); } } }); }, []);
  const setLanguage = (next: AppLanguage) => { setLanguageState(next); void AsyncStorage.setItem(LANGUAGE_KEY, next); };
  const updateTranslation = (key: string, spanish: string) => { setTranslationOverrides((current) => { const next = { ...current, [key]: spanish }; void AsyncStorage.setItem(TRANSLATION_OVERRIDES_KEY, JSON.stringify(next)); return next; }); };
  const t = (text: string) => translateText(text, language, translationOverrides);
  const value = useMemo(() => ({ language, setLanguage, t, translationOverrides, updateTranslation }), [language, translationOverrides]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}
export function useLanguage() { const context = useContext(LanguageContext); if (!context) throw new Error('useLanguage must be used within LanguageProvider'); return context; }
